INSERT INTO `v1_ba50002facee27f1cdd2955d06f745e5b31937bb95707b850fcf3adf3db15a8c` VALUES ("bgm_M199", "お兄ちゃん争奪！\nどっちのチョコがおいしいでSHOW", 1001, "2030/12/31 15:00:00", 1002, "bgm_M199_juke", 10000, "愛情たっぷりのチョコレートケー\nキを完成させよう！\n超キュートなタップゲーム！", "2030/12/31 15:00:00", "", "2020-02-15 15:00:00");
